/**
 * Every rect and anchor of the 04:00 cinema scene, so the painted layers, the video window, the beam, and the caption
 * stay aligned. Change numbers here, never in the component.
 *
 * Placement is authored in stage px (desktop stage 2560×1440 = `cinema-landscape`, mobile 1080×2340 =
 * `cinema-landscape-mobile`), starting from the suggested composition in docs/art/cinema/README.md, and exported as
 * percentages of the stage: `x`/`w` of its width, `y`/`h` of its height. Crops and anchors of the cropped layers come
 * from ./art.ts (generated by tools/optimize-art.mjs).
 */
import { ART } from './art.ts';

export interface Rect {
	x: number;
	y: number;
	w: number;
	h: number;
}

export interface Point {
	x: number;
	y: number;
}

export type Breakpoint = 'desktop' | 'mobile';

/** Below this width the mobile composition is used (frame on top, cliff below, vertical beam). Keep in sync with the CSS. */
export const MOBILE_MAX = '47.99rem';

const STAGE: Record<Breakpoint, { width: number; height: number }> = {
	desktop: { width: 2560, height: 1440 },
	mobile: { width: 1080, height: 2340 }
};

interface Placement {
	/** Video window = the frame's exact 16:9 aperture, in stage px (`h` follows from 16:9). */
	window: { x: number; y: number; w: number };
	/** Top of the caption (title + link) in stage px, and its alignment. */
	caption: { y: number; align: 'start' | 'center' };
	/** Uncropped 1600×1400 cliff master drawn at `scale` with its top left at (x, y). */
	cliff: { x: number; y: number; scale: number };
	/** Mascot seat contact point in stage px and its scale (1254 px master). */
	mascot: { x: number; y: number; scale: number };
	/** Where the beam's broad end lands: two points inside the frame (hidden behind the video). The apex is the laptop. */
	beamEnds: [Point, Point];
}

const PLACEMENT: Record<Breakpoint, Placement> = {
	desktop: {
		// README: frame box (880, 80) at scale 0.8 → video (1008, 259.2, 1344 × 756)
		window: { x: 1008, y: 259.2, w: 1344 },
		caption: { y: 1084, align: 'start' },
		// README: cliff box (0, 530) at scale 0.65, meeting the bottom edge
		cliff: { x: 0, y: 530, scale: 0.65 },
		// on the ledge (y ≈ 936) in the empty sitting area, left of the laptop
		mascot: { x: 402, y: 940, scale: 0.26 },
		// just inside the frame's left corners, so the cone opens to the frame's full height (as in the mockup)
		beamEnds: [
			{ x: 1070, y: 275 },
			{ x: 1070, y: 1000 }
		]
	},
	mobile: {
		// README: frame box (0, 440) at scale 0.54 → video (86.4, 560.96, 907.2 × 510.3)
		window: { x: 86.4, y: 560.96, w: 907.2 },
		caption: { y: 1166, align: 'center' },
		// README box (0, 1540) at scale 0.55, moved down 30 px so the rock meets the stage bottom
		cliff: { x: 0, y: 1570, scale: 0.55 },
		mascot: { x: 338, y: 1916, scale: 0.22 },
		beamEnds: [
			{ x: 150, y: 1010 },
			{ x: 930, y: 1010 }
		]
	}
};

const round = (value: number) => Math.round(value * 1000) / 1000;
const n = (value: number) => +value.toFixed(5);

export interface CinemaLayout {
	window: Rect;
	frame: Rect;
	caption: { x: number; y: number; w: number; align: 'start' | 'center' };
	cliff: Rect;
	mascot: Rect;
	/** Light cone: apex at the laptop screen, far ends inside the frame. */
	beam: { apex: Point; ends: [Point, Point] };
	/** Painted beam texture: box (stage %) at the stage origin and the CSS transform that maps its cone onto `beam`. */
	beamTexture: { w: number; h: number; transform: string };
	dust: (Point & { size: number; delay: number; duration: number; drift: Point })[];
}

/**
 * Affine map that sends the painted beam's apex and the two corners of its broad end onto the scene triangle, as a
 * CSS transform for an element of the cropped beam's size at the stage origin (transform-origin 0 0). The linear part
 * is unitless; the translation is given in percent of the element, so the transform scales with the stage.
 */
function beamTransform(apex: Point, [endA, endB]: [Point, Point]): string {
	// Apex and the two corners of the painted broad end (crop px)
	const { origin, endA: a, endB: b, width, height } = ART.beam;
	const s1 = { x: a.x - origin.x, y: a.y - origin.y };
	const s2 = { x: b.x - origin.x, y: b.y - origin.y };
	const t1 = { x: endA.x - apex.x, y: endA.y - apex.y };
	const t2 = { x: endB.x - apex.x, y: endB.y - apex.y };
	const det = s1.x * s2.y - s2.x * s1.y;
	// L = T · S⁻¹
	const l00 = (t1.x * s2.y - t2.x * s1.y) / det;
	const l01 = (t2.x * s1.x - t1.x * s2.x) / det;
	const l10 = (t1.y * s2.y - t2.y * s1.y) / det;
	const l11 = (t2.y * s1.x - t1.y * s2.x) / det;
	const tx = apex.x - (l00 * origin.x + l01 * origin.y);
	const ty = apex.y - (l10 * origin.x + l11 * origin.y);
	return `translate(${n((tx / width) * 100)}%, ${n((ty / height) * 100)}%) matrix(${n(l00)}, ${n(l10)}, ${n(l01)}, ${n(l11)}, 0, 0)`;
}

function build(bp: Breakpoint): CinemaLayout {
	const place = PLACEMENT[bp];
	const stage = STAGE[bp];
	const toRect = (x: number, y: number, w: number, h: number): Rect => ({
		x: round((x / stage.width) * 100),
		y: round((y / stage.height) * 100),
		w: round((w / stage.width) * 100),
		h: round((h / stage.height) * 100)
	});
	const toPoint = (p: Point): Point => ({ x: round((p.x / stage.width) * 100), y: round((p.y / stage.height) * 100) });

	// Video window and the frame scaled so its transparent aperture matches the window exactly
	const win = { ...place.window, h: (place.window.w * 9) / 16 };
	const frameScale = win.w / ART.frame.window.width;
	const frame = toRect(win.x - ART.frame.window.x * frameScale, win.y - ART.frame.window.y * frameScale, ART.frame.width * frameScale, ART.frame.height * frameScale);

	const { cliff: c } = place;
	const cliff = toRect(c.x + ART.cliff.crop.x * c.scale, c.y + ART.cliff.crop.y * c.scale, ART.cliff.width * c.scale, ART.cliff.height * c.scale);
	const apexPx = { x: c.x + (ART.cliff.crop.x + ART.cliff.laptop.x) * c.scale, y: c.y + (ART.cliff.crop.y + ART.cliff.laptop.y) * c.scale };

	const { mascot: mo } = place;
	const mascot = toRect(mo.x - ART.mascot.seat.x * mo.scale, mo.y - ART.mascot.seat.y * mo.scale, ART.mascot.width * mo.scale, ART.mascot.height * mo.scale);

	const apex = toPoint(apexPx);
	const ends: [Point, Point] = [toPoint(place.beamEnds[0]), toPoint(place.beamEnds[1])];
	const beamTexture = {
		w: round((ART.beam.width / stage.width) * 100),
		h: round((ART.beam.height / stage.height) * 100),
		transform: beamTransform(apexPx, place.beamEnds)
	};

	// A few dust motes spread through the cone (deterministic, so SSR and client agree).
	const [a, b] = ends;
	const dust = [0.22, 0.3, 0.38, 0.45, 0.52, 0.6, 0.68, 0.76, 0.84].map((t, index) => {
		const side = (((index * 7) % 9) / 8) * 1.2 - 0.6; // -0.6…0.6 across the cone
		const far = { x: (a.x + b.x) / 2 + ((b.x - a.x) / 2) * side, y: (a.y + b.y) / 2 + ((b.y - a.y) / 2) * side };
		return {
			x: round(apex.x + (far.x - apex.x) * t),
			y: round(apex.y + (far.y - apex.y) * t),
			size: 2 + (index % 3),
			delay: -((index * 1.7) % 9),
			duration: 7 + ((index * 3) % 6),
			drift: { x: ((index % 4) - 1.5) * 10, y: -14 - (index % 3) * 8 }
		};
	});

	const window = toRect(win.x, win.y, win.w, win.h);
	return {
		window,
		frame,
		caption: { x: window.x, y: round((place.caption.y / stage.height) * 100), w: window.w, align: place.caption.align },
		cliff,
		mascot,
		beam: { apex, ends },
		beamTexture,
		dust
	};
}

export const CINEMA_LAYOUT: Record<Breakpoint, CinemaLayout> = { desktop: build('desktop'), mobile: build('mobile') };

const pct = (value: number) => `${round(value)}%`;

/** Inline CSS vars for an element placed on both stages: `--dx --dy --dw --dh` (desktop) and `--mx …` (mobile). */
export function placeVars(desktop: Partial<Rect> & Point, mobile: Partial<Rect> & Point): string {
	const vars: string[] = [];
	for (const [prefix, rect] of [
		['d', desktop],
		['m', mobile]
	] as const) {
		vars.push(`--${prefix}x: ${pct(rect.x)}`, `--${prefix}y: ${pct(rect.y)}`);
		if (rect.w !== undefined) vars.push(`--${prefix}w: ${pct(rect.w)}`);
		if (rect.h !== undefined) vars.push(`--${prefix}h: ${pct(rect.h)}`);
	}
	return vars.join('; ');
}

/** Soft-edged light cone as a CSS mask (SVG polygon in stage percentages, blurred). */
export function beamMask(bp: Breakpoint): string {
	const { apex, ends } = CINEMA_LAYOUT[bp].beam;
	const points = [apex, ends[0], ends[1]].map((p) => `${round(p.x)},${round(p.y)}`).join(' ');
	const svg =
		`<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100' preserveAspectRatio='none'>` +
		`<filter id='b' x='-20%' y='-20%' width='140%' height='140%'><feGaussianBlur stdDeviation='0.9'/></filter>` +
		`<polygon points='${points}' fill='white' filter='url(%23b)'/></svg>`;
	return `url("data:image/svg+xml,${svg.replaceAll('<', '%3C').replaceAll('>', '%3E')}")`;
}
